CREATE TABLE "Employee" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar(100) NOT NULL,
  "department" varchar(100) NOT NULL,
  "position" varchar(100) NOT NULL,
  "phone" varchar(20),
  "email" varchar(255),
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "Card" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" int NOT NULL,
  "number" varchar(20) UNIQUE NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'active',
  "issued_at" timestamp NOT NULL DEFAULT (now()),
  "blocked_at" timestamp
);

CREATE TABLE "Zone" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) NOT NULL,
  "description" text,
  "level_id" int NOT NULL
);

CREATE TABLE "AccessLevel" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) NOT NULL,
  "description" text
);

CREATE TABLE "Request" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" int NOT NULL,
  "card_id" int NOT NULL,
  "zone_id" int NOT NULL,
  "controller_id" int NOT NULL,
  "event_time" timestamp NOT NULL DEFAULT (now()),
  "direction" varchar(10) NOT NULL
);

CREATE TABLE "Controller" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "zone_id" int NOT NULL,
  "name" varchar(100) NOT NULL,
  "location" varchar(255),
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "StatusHistory" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "card_id" int NOT NULL,
  "old_status" varchar(20) NOT NULL,
  "new_status" varchar(20) NOT NULL,
  "changed_at" timestamp NOT NULL DEFAULT (now())
);

ALTER TABLE "Card" ADD FOREIGN KEY ("employee_id") REFERENCES "Employee" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Zone" ADD FOREIGN KEY ("level_id") REFERENCES "AccessLevel" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Request" ADD FOREIGN KEY ("employee_id") REFERENCES "Employee" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Request" ADD FOREIGN KEY ("card_id") REFERENCES "Card" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Request" ADD FOREIGN KEY ("zone_id") REFERENCES "Zone" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Request" ADD FOREIGN KEY ("controller_id") REFERENCES "Controller" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Controller" ADD FOREIGN KEY ("zone_id") REFERENCES "Zone" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "StatusHistory" ADD FOREIGN KEY ("card_id") REFERENCES "Card" ("id") DEFERRABLE INITIALLY IMMEDIATE;
